import json
def find_starts(I):
    n=len(I); w=len(I[0]); starts=[]
    for r in range(n):
        for c in range(w):
            col=I[r][c]
            if not col: continue
            up = r>0 and I[r-1][c]==col
            left = c>0 and I[r][c-1]==col
            ul = r>0 and c>0 and I[r-1][c-1]==col
            if not up and not left and not ul:
                horiz = c+1<w and I[r][c+1]==col
                starts.append((r,c,col,horiz))
    return starts

def transform(I):
    n=len(I); w=len(I[0])
    starts=find_starts(I)
    m=len(starts)
    S={}
    for r,c,col,horiz in starts:
        k = r%m if horiz else (c-r)%m
        if k in S:
            k=next(j for j in range(m) if j not in S)
        S[k]=col
    horiz_line = starts[0][3]
    def val(r,c):
        k = r%m if horiz_line else (c-r)%m
        return S.get(k,0)
    return [[val(r,c) for c in range(w)] for r in range(n)]

